private static BaseFont CreateUnicodeFont(bool bold, bool italic)
{
    BaseFont cached = GetCachedFont(bold, italic);
    if (cached != null)
        return cached;
    lock (_fontSync)
    {
        cached = GetCachedFont(bold, italic);
        if (cached != null)
            return cached;
        string strFontFile = "times.ttf";
        if (bold && italic)
            strFontFile = "timesbi.ttf";
        else if (bold)
            strFontFile = "timesbd.ttf";
        else if (italic)
            strFontFile = "timesi.ttf";
        string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), strFontFile);
        if (!File.Exists(strFontPath))
            strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "times.ttf");
        if (!File.Exists(strFontPath))
            strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");
        if (!File.Exists(strFontPath))
            cached = BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);
        else
            cached = BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        SetCachedFont(bold, italic, cached);
        return cached;
    }
}
private static BaseFont GetCachedFont(bool bold, bool italic)
{
    if (bold && italic)
        return _bfBoldItalic;
    if (bold)
        return _bfBold;
    if (italic)
        return _bfItalic;
    return _bfRegular;
}
private static void SetCachedFont(bool bold, bool italic, BaseFont value)
{
    if (bold && italic)
        _bfBoldItalic = value;
    else if (bold)
        _bfBold = value;
    else if (italic)
        _bfItalic = value;
    else
        _bfRegular = value;
}

